INSERT INTO candidate_applications (id, candidate_id, referral_source, referral_source_other, mej_acknowledged, experience, motivation, saturday_restriction, special_needs, created_at) VALUES
  ('8033916c-7754-4625-b99e-1eaf8c7f082b', '61efcef6-43ed-4bcf-9149-d6703988cda8', 'instagram', NULL, 1, 'Tenho experiência com projetos pessoais em Python, principalmente automação de tarefas simples. Trabalhei como monitor de uma disciplina de cálculo, o que me ensinou bastante sobre didática. Participei de uma maratona de programação e cheguei à fase estadual.', 'Quero sair da teoria da sala de aula e aplicar o que aprendo em problemas reais. Tenho interesse em empreendedorismo e vejo a empresa júnior como o primeiro passo nessa direção.', 0, 0, '2024-01-31 17:48:03'),
  ('3324d4f4-3f77-4943-a7bc-7aaf14309f3e', '09f029b2-d75d-42b8-bdf3-c317c7f08f6c', 'campus', NULL, 1, 'Tenho experiência com projetos pessoais em Python, principalmente automação de tarefas simples.', 'Acredito que aprender fazendo é mais efetivo do que só estudar para prova.', 0, 0, '2024-03-08 05:06:33'),
  ('707460e6-7624-43eb-b2a3-c3cf9aca5c1f', '8e26ee3a-0df4-454a-bd1d-02a1c5bf78a6', 'indicacao', NULL, 1, 'Já estagiei por alguns meses numa construtora, acompanhando o setor de planejamento. Fui representante de turma por dois semestres, o que me deu prática em organizar pessoas. Tenho experiência com Excel avançado de um estágio anterior em uma pequena empresa familiar.', 'Quero um ambiente onde eu possa errar, aprender rápido e crescer profissionalmente. Sempre ouvi falar bem da empresa júnior e quero fazer parte da próxima geração.', 0, 0, '2024-05-17 09:06:03'),
  ('62b4209b-f43f-4cf1-a122-421a41a97e5b', 'd4b89bdd-8b34-45db-b43c-4e3e90d6a41c', 'outros', 'Vi uma matéria sobre a empresa júnior no site da universidade.', 1, 'Fui representante de turma por dois semestres, o que me deu prática em organizar pessoas. Participei de uma equipe de competição de Fórmula SAE cuidando da parte estrutural.', 'Quero sair da minha zona de conforto e assumir mais responsabilidade do que hoje na faculdade.', 0, 0, '2024-02-02 02:19:02'),
  ('40c104ca-9d7d-4707-b2fe-d3a39eb7b730', 'd8af14ea-675d-42c7-8280-9e1efc5ff220', 'instagram', NULL, 1, 'Já ajudei a organizar a semana acadêmica do meu curso, cuidando da parte de logística. Tenho experiência com projetos pessoais em Python, principalmente automação de tarefas simples. Participei de um hackathon universitário e ficamos entre os três primeiros colocados.', 'Busco desenvolver soft skills como trabalho em equipe e comunicação, que a faculdade não ensina sozinha. Vejo a empresa júnior como uma ponte entre a universidade e o mercado de trabalho.', 0, 0, '2024-06-01 18:21:10'),
  ('d9567b65-2999-45dc-a6eb-18ccd86bddc6', '8c737900-e4a5-4815-bb45-9b5345ff25ab', 'instagram', NULL, 1, 'Tenho experiência com Excel avançado de um estágio anterior em uma pequena empresa familiar. Já estagiei por alguns meses numa construtora, acompanhando o setor de planejamento.', 'Sempre ouvi falar bem da empresa júnior e quero fazer parte da próxima geração.', 0, 0, '2024-01-18 03:19:47'),
  ('952b852c-e5e3-4b73-a1ea-2f9b128589a9', '6600c557-f316-487b-b262-657368d3633b', 'linkedin', NULL, 1, 'Tenho experiência com projetos pessoais em Python, principalmente automação de tarefas simples.', 'Quero construir um currículo mais forte antes de buscar meu primeiro estágio. Quero um ambiente onde eu possa errar, aprender rápido e crescer profissionalmente.', 0, 0, '2024-01-19 15:17:49'),
  ('cb053304-e3e2-4bb2-b8c7-08f29f823986', 'f6d06d7e-14cf-4705-b619-6c44cf5cee4b', 'indicacao', NULL, 1, 'Participei de uma maratona de programação e cheguei à fase estadual.', 'Sempre ouvi falar bem da empresa júnior e quero fazer parte da próxima geração.', 0, 0, '2024-01-30 21:17:25'),
  ('82c9d861-e5ad-48de-af0d-276201294a0b', '4e381031-fb09-4d48-8223-2065365ffd4a', 'indicacao', NULL, 1, 'Já ajudei a organizar a semana acadêmica do meu curso, cuidando da parte de logística. Fiz um curso técnico antes da faculdade, então já tenho alguma vivência prática de laboratório. Participei de uma maratona de programação e cheguei à fase estadual.', 'Quero construir um currículo mais forte antes de buscar meu primeiro estágio. Sempre ouvi falar bem da empresa júnior e quero fazer parte da próxima geração.', 0, 0, '2024-03-25 23:11:38'),
  ('02b079fb-cc1d-4e9b-b35f-d8b9dc556eb3', 'a7bdc6d3-d5d4-49a2-9741-41794ebb8fcc', 'instagram', NULL, 1, 'Fiz um curso técnico antes da faculdade, então já tenho alguma vivência prática de laboratório. Tenho experiência com Excel avançado de um estágio anterior em uma pequena empresa familiar.', 'Tenho interesse em empreendedorismo e vejo a empresa júnior como o primeiro passo nessa direção. Quero um ambiente onde eu possa errar, aprender rápido e crescer profissionalmente.', 0, 0, '2024-06-18 11:27:56'),
