INSERT INTO candidate_applications (id, candidate_id, referral_source, referral_source_other, mej_acknowledged, experience, motivation, saturday_restriction, special_needs, created_at) VALUES
  ('b8cff178-0755-4b1b-b85d-0fa073671dc5', 'c999ed26-953e-4ce1-bf9b-06daf5bafd4b', 'instagram', NULL, 1, 'Fui voluntário em uma ONG local organizando oficinas de tecnologia para adolescentes. Nunca trabalhei formalmente ainda, mas participo de grupos de estudo e iniciação científica. Já participei de uma liga de robótica na faculdade, onde ajudei a montar e programar o protótipo.', 'Sempre ouvi falar bem da empresa júnior e quero fazer parte da próxima geração. Quero construir um currículo mais forte antes de buscar meu primeiro estágio.', 0, 0, '2025-10-25 14:54:28'),
  ('f6587797-5769-421b-8261-e44f5191929d', '2f1c1cd6-286b-444a-bb43-232494a44d6e', 'outros', 'Um colega de outro curso comentou e resolvi me inscrever.', 1, 'Fiz um projeto de extensão universitária relacionado a energia solar durante um semestre. Trabalhei como monitor de uma disciplina de cálculo, o que me ensinou bastante sobre didática. Fui voluntário em uma ONG local organizando oficinas de tecnologia para adolescentes.', 'Sempre ouvi falar bem da empresa júnior e quero fazer parte da próxima geração.', 0, 0, '2025-08-15 13:54:20'),
  ('6b8f7219-9c35-4fae-8e36-f99f01299f32', '5281a9e2-fe9f-44e7-8af5-c442931960ea', 'campus', NULL, 1, 'Tenho experiência com projetos pessoais em Python, principalmente automação de tarefas simples.', 'Quero um ambiente onde eu possa errar, aprender rápido e crescer profissionalmente.', 0, 0, '2025-11-01 08:10:56'),
  ('bf63ab7b-658b-44de-9274-d989af27c6f9', '17c33f54-07a8-4661-9cec-95e5df2d1159', 'instagram', NULL, 1, 'Participei de um hackathon universitário e ficamos entre os três primeiros colocados.', 'Vejo a empresa júnior como uma ponte entre a universidade e o mercado de trabalho.', 1, 0, '2025-12-29 22:47:04'),
  ('86a0efe1-bb14-44e0-9846-0357ea9051eb', '228ede77-7dca-4b19-9d3d-9b2a5aeefbbb', 'instagram', NULL, 1, 'Fiz um curso técnico antes da faculdade, então já tenho alguma vivência prática de laboratório.', 'Quero construir um currículo mais forte antes de buscar meu primeiro estágio. Quero um ambiente onde eu possa errar, aprender rápido e crescer profissionalmente.', 0, 0, '2025-09-11 04:06:03'),
  ('b73a58ec-9d8e-4bee-a025-da30db4c8195', '0fcbf87c-b40b-4de2-925d-1e9ee7913753', 'campus', NULL, 1, 'Já participei de uma liga de robótica na faculdade, onde ajudei a montar e programar o protótipo.', 'Sempre ouvi falar bem da empresa júnior e quero fazer parte da próxima geração. Busco desenvolver soft skills como trabalho em equipe e comunicação, que a faculdade não ensina sozinha.', 0, 0, '2025-11-02 02:20:53'),
  ('301ff2e1-cd57-4308-b7da-e134f7f36ca8', 'ba83c74e-850a-486f-8b6a-56d422f99abb', 'instagram', NULL, 1, 'Participei de um hackathon universitário e ficamos entre os três primeiros colocados. Nunca trabalhei formalmente ainda, mas participo de grupos de estudo e iniciação científica.', 'Acredito que aprender fazendo é mais efetivo do que só estudar para prova. Tenho interesse em empreendedorismo e vejo a empresa júnior como o primeiro passo nessa direção.', 1, 0, '2025-10-12 04:29:04'),
  ('2b3113ea-2f49-4eeb-8c17-87d10a827474', '181cbf3c-5506-492e-8f85-6d33328b62e2', 'indicacao', NULL, 1, 'Participei de uma equipe de competição de Fórmula SAE cuidando da parte estrutural. Participei de um hackathon universitário e ficamos entre os três primeiros colocados. Trabalhei como monitor de uma disciplina de cálculo, o que me ensinou bastante sobre didática.', 'Sempre ouvi falar bem da empresa júnior e quero fazer parte da próxima geração. Quero conhecer pessoas de outros períodos e cursos que compartilham os mesmos interesses.', 0, 0, '2025-11-18 20:52:47'),
  ('7ab7eccf-432d-4626-84d1-cc71271f6187', 'a07be9e7-35d7-4682-959a-485c456e8fb8', 'instagram', NULL, 1, 'Já estagiei por alguns meses numa construtora, acompanhando o setor de planejamento. Participei de um hackathon universitário e ficamos entre os três primeiros colocados.', 'Vejo a empresa júnior como uma ponte entre a universidade e o mercado de trabalho.', 0, 0, '2025-08-04 10:33:13'),
  ('923741af-75a5-4758-a6b3-20cfe29f416b', '06919b71-6930-42e6-820b-9b06e0969e4d', 'instagram', NULL, 1, 'Tenho experiência com projetos pessoais em Python, principalmente automação de tarefas simples. Fui representante de turma por dois semestres, o que me deu prática em organizar pessoas.', 'Sempre ouvi falar bem da empresa júnior e quero fazer parte da próxima geração. Tenho interesse em empreendedorismo e vejo a empresa júnior como o primeiro passo nessa direção.', 0, 0, '2025-10-03 08:28:10'),
