INSERT INTO candidate_applications (id, candidate_id, referral_source, referral_source_other, mej_acknowledged, experience, motivation, saturday_restriction, special_needs, created_at) VALUES
  ('3649e398-8966-4f5f-99fd-de302e1aec32', '3e2668c3-f9d5-455b-9a40-99acc112d0cb', 'indicacao', NULL, 1, 'Participei de um hackathon universitário e ficamos entre os três primeiros colocados.', 'Busco desenvolver liderança, já que pretendo seguir carreira de gestão no futuro. Acredito que aprender fazendo é mais efetivo do que só estudar para prova.', 1, 1, '2026-02-06 02:42:15'),
  ('800d525f-9261-444c-8637-04c635f537b0', 'e164b547-6888-469a-8065-cc144f51167f', 'instagram', NULL, 1, 'Fiz um projeto de extensão universitária relacionado a energia solar durante um semestre. Nunca trabalhei formalmente ainda, mas participo de grupos de estudo e iniciação científica.', 'Busco desenvolver soft skills como trabalho em equipe e comunicação, que a faculdade não ensina sozinha. Quero um ambiente onde eu possa errar, aprender rápido e crescer profissionalmente.', 1, 0, '2026-07-28 00:09:13'),
  ('ebb1c4cf-2dbb-4732-bb51-01c68a80e9ef', '0bad9c01-9023-4598-b765-77e1ea1cff6a', 'instagram', NULL, 1, 'Fiz um curso técnico antes da faculdade, então já tenho alguma vivência prática de laboratório. Já participei de uma liga de robótica na faculdade, onde ajudei a montar e programar o protótipo. Fiz um projeto de extensão universitária relacionado a energia solar durante um semestre.', 'Busco desenvolver soft skills como trabalho em equipe e comunicação, que a faculdade não ensina sozinha.', 0, 0, '2026-02-19 00:17:44'),
  ('bbb1d4b5-7e46-48ca-9a26-93045a245c82', '7360e0d7-8138-42f0-9845-457aadcdf0fc', 'campus', NULL, 1, 'Tenho experiência com Excel avançado de um estágio anterior em uma pequena empresa familiar.', 'Já pesquisei sobre os projetos que vocês desenvolvem e me identifiquei bastante.', 0, 0, '2026-01-01 01:47:04'),
  ('632ab44f-fa8b-46d3-9424-20fc2e111423', 'bfba0d12-9a6e-42b3-b3fa-359463b78736', 'campus', NULL, 1, 'Participei de uma maratona de programação e cheguei à fase estadual. Fiz um projeto de extensão universitária relacionado a energia solar durante um semestre. Fiz um curso técnico antes da faculdade, então já tenho alguma vivência prática de laboratório.', 'Acredito que aprender fazendo é mais efetivo do que só estudar para prova.', 0, 0, '2026-07-19 11:32:09'),
  ('93fe3cce-5441-4171-a22c-1b33de4a5ad8', 'd78aa1b1-9f8d-4f6f-b6ab-1c08a88c8de0', 'outros', 'Encontrei o formulário compartilhado no Discord da faculdade.', 1, 'Fui voluntário em uma ONG local organizando oficinas de tecnologia para adolescentes.', 'Tenho interesse em empreendedorismo e vejo a empresa júnior como o primeiro passo nessa direção.', 0, 0, '2026-01-29 02:21:30'),
  ('68624dc1-1514-4b26-ae88-d0765cb763cd', '1408b2ee-3c13-489d-869c-78a9d1d994fa', 'instagram', NULL, 1, 'Já estagiei por alguns meses numa construtora, acompanhando o setor de planejamento. Trabalhei como monitor de uma disciplina de cálculo, o que me ensinou bastante sobre didática.', 'Quero construir um currículo mais forte antes de buscar meu primeiro estágio. Sempre ouvi falar bem da empresa júnior e quero fazer parte da próxima geração.', 1, 0, '2026-06-11 05:28:40'),
  ('ca9f603e-d5b4-4536-8cf1-b04e5f3222dc', '1dd004c1-867c-4a10-bba1-2bd2d3050ee7', 'indicacao', NULL, 1, 'Fiz um projeto de extensão universitária relacionado a energia solar durante um semestre. Tenho experiência com projetos pessoais em Python, principalmente automação de tarefas simples. Tenho experiência com Excel avançado de um estágio anterior em uma pequena empresa familiar.', 'Quero construir um currículo mais forte antes de buscar meu primeiro estágio.', 0, 0, '2026-07-19 21:04:32'),
  ('a3f573f6-b3cc-4316-864c-528bdd22020b', '394cbd7f-bd60-4861-92e3-3c8dd3afaa6d', 'instagram', NULL, 1, 'Fiz um projeto de extensão universitária relacionado a energia solar durante um semestre.', 'Quero conhecer pessoas de outros períodos e cursos que compartilham os mesmos interesses.', 1, 0, '2026-02-09 14:16:14'),
  ('ed1ff768-63e6-40c6-b608-81dc676bc6ea', '380450a1-5dc7-474c-9626-e5f8a89bccd3', 'indicacao', NULL, 1, 'Tenho experiência com projetos pessoais em Python, principalmente automação de tarefas simples. Trabalhei como monitor de uma disciplina de cálculo, o que me ensinou bastante sobre didática.', 'Quero conhecer pessoas de outros períodos e cursos que compartilham os mesmos interesses.', 0, 1, '2026-04-16 18:17:41'),
