INSERT INTO candidate_applications (id, candidate_id, referral_source, referral_source_other, mej_acknowledged, experience, motivation, saturday_restriction, special_needs, created_at) VALUES
  ('023cd1fd-58b4-4722-afc8-0d87c9c7eb31', 'bdf4be86-e732-4832-be91-2529ab15c037', 'campus', NULL, 1, 'Fiz um curso técnico antes da faculdade, então já tenho alguma vivência prática de laboratório.', 'Quero conhecer pessoas de outros períodos e cursos que compartilham os mesmos interesses. Acredito que aprender fazendo é mais efetivo do que só estudar para prova.', 0, 0, '2026-08-04 13:10:43'),
  ('b9cb2c2b-e341-41e5-b4b8-dd8a3896a0e1', 'db39a9f1-ebcc-4d23-885d-515752ea2837', 'outros', 'Encontrei o formulário compartilhado no Discord da faculdade.', 1, 'Participei de uma maratona de programação e cheguei à fase estadual.', 'Busco desenvolver liderança, já que pretendo seguir carreira de gestão no futuro.', 0, 0, '2026-08-12 01:21:18'),
  ('9dbff537-f087-43a4-bbb5-8d887d4bac83', '3901a5af-4a82-4f66-b034-619194fd71c6', 'instagram', NULL, 1, 'Tenho experiência com projetos pessoais em Python, principalmente automação de tarefas simples.', 'Busco desenvolver liderança, já que pretendo seguir carreira de gestão no futuro.', 0, 0, '2026-08-03 19:10:48'),
  ('6c878716-ac73-4975-88fb-2f8954116ad9', 'fed7f5e1-9b77-46e2-abe5-e45375d38aa5', 'instagram', NULL, 1, 'Nunca trabalhei formalmente ainda, mas participo de grupos de estudo e iniciação científica. Participei de uma maratona de programação e cheguei à fase estadual. Já ajudei a organizar a semana acadêmica do meu curso, cuidando da parte de logística.', 'Busco desenvolver soft skills como trabalho em equipe e comunicação, que a faculdade não ensina sozinha. Acredito que aprender fazendo é mais efetivo do que só estudar para prova.', 0, 0, '2026-08-15 08:21:25'),
  ('e842c1cf-4a6e-41cd-a2f9-cf69a673fea0', '2a5c2beb-768f-4ef5-8266-166605fbc2d9', 'indicacao', NULL, 1, 'Já ajudei a organizar a semana acadêmica do meu curso, cuidando da parte de logística. Fiz um projeto de extensão universitária relacionado a energia solar durante um semestre. Já estagiei por alguns meses numa construtora, acompanhando o setor de planejamento.', 'Sempre ouvi falar bem da empresa júnior e quero fazer parte da próxima geração.', 0, 0, '2026-08-09 11:10:57'),
  ('2cbe39bb-738d-433a-bfe8-97e227ad14ba', '3ffd8e7a-9a45-43a8-a27f-bc758b7026d3', 'indicacao', NULL, 1, 'Participei de um hackathon universitário e ficamos entre os três primeiros colocados. Fiz um curso técnico antes da faculdade, então já tenho alguma vivência prática de laboratório. Tenho experiência com Excel avançado de um estágio anterior em uma pequena empresa familiar.', 'Vejo a empresa júnior como uma ponte entre a universidade e o mercado de trabalho.', 1, 0, '2026-08-17 02:52:28'),
  ('2b9c16c8-a051-4db6-88c7-a94a9db75dc9', '441e60ea-d6ea-4110-8909-20e30d70b7a6', 'instagram', NULL, 1, 'Já participei de uma liga de robótica na faculdade, onde ajudei a montar e programar o protótipo. Fui voluntário em uma ONG local organizando oficinas de tecnologia para adolescentes. Trabalhei como monitor de uma disciplina de cálculo, o que me ensinou bastante sobre didática.', 'Quero sair da minha zona de conforto e assumir mais responsabilidade do que hoje na faculdade.', 0, 0, '2026-08-18 02:00:38'),
  ('b40a4318-19f1-4e2c-903f-e2fd8324b38a', 'a787cc43-6bb8-4db2-af19-b2505569e6e8', 'indicacao', NULL, 1, 'Fui representante de turma por dois semestres, o que me deu prática em organizar pessoas.', 'Busco desenvolver soft skills como trabalho em equipe e comunicação, que a faculdade não ensina sozinha.', 0, 0, '2026-08-10 02:26:57'),
  ('a8ac01f6-8f92-4112-80d2-2c0c5ec18aa9', 'ce7661c6-5a0b-4f26-a15c-14c1569453d7', 'outros', 'Encontrei pesquisando sobre empresas juniores de engenharia.', 1, 'Já estagiei por alguns meses numa construtora, acompanhando o setor de planejamento.', 'Busco desenvolver liderança, já que pretendo seguir carreira de gestão no futuro.', 0, 0, '2026-08-18 12:23:33'),
  ('960920b1-f436-4323-8c51-6dde90886c9f', '48b22799-c88e-400f-b953-b8d5937077f4', 'campus', NULL, 1, 'Fui representante de turma por dois semestres, o que me deu prática em organizar pessoas. Participei de uma maratona de programação e cheguei à fase estadual.', 'Busco desenvolver liderança, já que pretendo seguir carreira de gestão no futuro.', 0, 1, '2026-08-07 14:35:15'),
  ('d4608a04-4689-48ce-81dd-34d77f041582', '04b10190-389f-4e38-ae5a-27f5d9b395e1', 'instagram', NULL, 1, 'Fiz um curso técnico antes da faculdade, então já tenho alguma vivência prática de laboratório. Tenho experiência com Excel avançado de um estágio anterior em uma pequena empresa familiar. Participei de um hackathon universitário e ficamos entre os três primeiros colocados.', 'Acredito que aprender fazendo é mais efetivo do que só estudar para prova. Quero sair da teoria da sala de aula e aplicar o que aprendo em problemas reais.', 1, 0, '2026-08-05 16:00:10'),
  ('3938fa89-63a4-45ca-99f3-de7031ee2047', 'cdfab951-233a-4fb7-8752-f64f12987574', 'indicacao', NULL, 1, 'Participei de um hackathon universitário e ficamos entre os três primeiros colocados. Participei de uma equipe de competição de Fórmula SAE cuidando da parte estrutural. Já ajudei a organizar a semana acadêmica do meu curso, cuidando da parte de logística.', 'Quero um ambiente onde eu possa errar, aprender rápido e crescer profissionalmente.', 0, 0, '2026-08-01 17:51:49'),
  ('bbd0f94a-a6f0-4b46-8833-5cdb69294eae', 'db22b588-7178-469e-940a-56a8a57144e5', 'instagram', NULL, 1, 'Trabalhei como monitor de uma disciplina de cálculo, o que me ensinou bastante sobre didática. Tenho experiência com projetos pessoais em Python, principalmente automação de tarefas simples. Fiz um curso técnico antes da faculdade, então já tenho alguma vivência prática de laboratório.', 'Quero construir um currículo mais forte antes de buscar meu primeiro estágio. Já pesquisei sobre os projetos que vocês desenvolvem e me identifiquei bastante.', 0, 0, '2026-08-07 23:13:58'),
  ('5343ef6b-52b5-4beb-a1bd-86de0b6094a6', '973d9dbe-dc63-4f31-a80a-d58af9bd3456', 'campus', NULL, 1, 'Já ajudei a organizar a semana acadêmica do meu curso, cuidando da parte de logística.', 'Quero sair da minha zona de conforto e assumir mais responsabilidade do que hoje na faculdade.', 0, 0, '2026-08-11 03:06:24'),
  ('fc7b4c3c-f17b-4fda-9e44-598efa79fa09', 'ec4e6c68-c27a-4693-92ce-d03562d6b48d', 'outros', 'Vi uma matéria sobre a empresa júnior no site da universidade.', 1, 'Participei de uma equipe de competição de Fórmula SAE cuidando da parte estrutural.', 'Vejo a empresa júnior como uma ponte entre a universidade e o mercado de trabalho. Quero sair da minha zona de conforto e assumir mais responsabilidade do que hoje na faculdade.', 1, 0, '2026-08-12 14:49:32'),
  ('bf300ebe-7e73-4b4a-b4ca-cb69f1779244', '4243169e-e7e1-4a7b-ac46-9f418459fd71', 'campus', NULL, 1, 'Fui representante de turma por dois semestres, o que me deu prática em organizar pessoas.', 'Já pesquisei sobre os projetos que vocês desenvolvem e me identifiquei bastante. Sempre ouvi falar bem da empresa júnior e quero fazer parte da próxima geração.', 0, 0, '2026-08-06 19:30:07'),
  ('17282703-6b1e-45d1-bbae-440951144d1f', '1492b050-40e3-48a0-8eb7-1bc89b7b7be9', 'instagram', NULL, 1, 'Já participei de uma liga de robótica na faculdade, onde ajudei a montar e programar o protótipo.', 'Quero conhecer pessoas de outros períodos e cursos que compartilham os mesmos interesses. Quero sair da teoria da sala de aula e aplicar o que aprendo em problemas reais.', 1, 0, '2026-08-19 18:22:24'),
